ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'public/automation/reference-corpus'
DISCLAIMER = '강사 제작 가상 교육사업 문서. 실제 울산대학교·기관의 정책, 공문, 성과, 법적 기준이 아닙니다.'
BASE = 'automation/reference-corpus/'
DOCS = []
EXPECTED = []


def add(id, title, category, summary, sections, *, status='current', version='1.0',
        date='2026-11-06', scope='R01·R02 가상 교육사업', parents=('B01',), related=()):
    DOCS.append(dict(id=id, title=title, category=category, version=version,
                     effectiveDate=date, status=status, scope=scope,
                     parentIds=list(parents), relatedIds=list(related), summary=summary,
                     path=f'{BASE}documents/{id}.txt', htmlPath=f'{BASE}documents/{id}.html',
                     sections=[dict(id=f's{i}', title=t, text=x) for i, (t, x) in enumerate(sections, 1)]))


