STYLE='''body{font-family:"Malgun Gothic",sans-serif;line-height:1.85;color:#20352a;background:#f6f8f2;margin:0}main{max-width:920px;margin:auto;padding:32px 24px}article{background:white;border:1px solid #c9d5c5;padding:24px;margin:24px 0}h1{font-size:1.8rem}h2{font-size:1.35rem}h3{font-size:1.12rem}p{white-space:pre-wrap;overflow-wrap:anywhere}.notice{background:#fff1cf;border-left:5px solid #8c6625;padding:16px}.meta{color:#476343}a{color:#1e5c39}input{font-size:1rem;width:95%;padding:12px}nav a{display:inline-block;padding:6px}section:target,article:target{outline:3px solid #65813d}small{display:block}button{padding:10px}.hidden{display:none}@media print{nav,input,button{display:none}body{background:white}article{break-inside:avoid}a{color:inherit}}'''


def page(title,body,script=''):
    return '<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+STYLE+'</style><main>'+body+'</main>'+script+'</html>'


def article(d, local=False):
    e=html.escape
    related=' '.join(f'<a href="{("" if local else "documents/")}{id}.html">{id}</a>' for id in d['relatedIds'])
    return f'<article id="{d["id"]}" data-status="{d["status"]}"><h2>{d["id"]} · {e(d["title"])}</h2><p class="meta">{e(d["category"])} | v{e(d["version"])} | 시행 {d["effectiveDate"]} | 상태 {d["status"]}<br>범위: {e(d["scope"])} | 상위: {e(", ".join(d["parentIds"]) or "기존 운영기준 원문")}</p><p>{e(d["summary"])}</p>'+''.join(f'<section id="{s["id"] if local else d["id"]+"-"+s["id"]}"><h3>{s["id"]} · {e(s["title"])}</h3><p>{e(s["text"])}</p></section>' for s in d['sections'])+f'<p>관련 문서: {related}</p></article>'


def plaintext(d):
    return f"{d['id']} | {d['title']}\n{DISCLAIMER}\n분류: {d['category']} | 버전: {d['version']} | 시행일: {d['effectiveDate']} | 상태: {d['status']}\n적용: {d['scope']} | 상위: {', '.join(d['parentIds']) or '없음'}\n요약: {d['summary']}\n\n"+'\n\n'.join(f"{s['id']} {s['title']}\n{s['text']}" for s in d['sections'])+'\n\n관련: '+', '.join(d['relatedIds'])+'\n'


def validate(corpus):
    ids={d['id'] for d in DOCS}
    assert len(ids)==72
    for d in DOCS:
        for ref in d['parentIds']+d['relatedIds']:
            assert ref in ids,(d['id'],ref)
        for key in ['path','htmlPath']:
            assert (ROOT/'public'/d[key]).is_file(), d[key]
        assert all(len(s['text'])>=20 for s in d['sections']),d['id']
    for q in corpus['questions']:
        assert len(set(e['documentId'] for e in q['evidence']))>=2
        for e in q['evidence']:
            d=next(x for x in DOCS if x['id']==e['documentId'])
            assert any(s['id']==e['sectionId'] and e['quote']==s['text'] for s in d['sections'])
            assert e['documentId'] in q['coreDocumentIds']
    text=[d['summary']+'\n'+'\n'.join(s['text'] for s in d['sections'] if s['title'] not in ('보관 범위','변경 이력')) for d in DOCS]
    hashes=[hashlib.sha256(x.encode()).hexdigest() for x in text]
    assert len(set(hashes))==len(hashes)
    # Character 5-gram Jaccard detects copy inflation without treating shared metadata as content.
    grams=[{x[i:i+5] for i in range(len(x)-4)} for x in text]
    highest=(0,None,None)
    for i in range(len(grams)):
        for j in range(i):
            score=len(grams[i]&grams[j])/len(grams[i]|grams[j])
            if score>highest[0]:highest=(score,DOCS[j]['id'],DOCS[i]['id'])
    assert highest[0]<0.65,highest
    rounds=corpus['baseline']['rounds']
    for m in rounds.values():
        assert m['rawRows']==m['validApplicants']+m['excludedRows']+m['heldRows']
        assert m['participants']==m['validResponses']+m['missingSatisfaction']+m['invalidSatisfaction']
        assert sum(m['programParticipants'].values())==m['participants']
    assert '27,379/7,181' in EXPECTED[3]['expected']
    assert '27,961/7,340' in EXPECTED[5]['expected']
    return dict(documentCount=len(DOCS),exactDuplicateCount=len(hashes)-len(set(hashes)),
                maxBodyFiveGramJaccard=round(highest[0],4),mostSimilarPair=list(highest[1:]),
                uniqueCategories=len(set(d['category'] for d in DOCS)),
                statuses=dict(collections.Counter(d['status'] for d in DOCS)),
                sectionCount=sum(len(d['sections']) for d in DOCS),
                questionCount=len(corpus['questions']),multiDocumentRequestsVerified=True,
                allDocumentLinksExist=True,baselineArithmeticVerified=True,
                method='문서 고유 본문 5 글자 집합 Jaccard(공통 메타 데이터· 보관 범위· 변경 이력 제외); 동일 본문 SHA256; 실제 경로· 절· 인용문· 산술 보존 검증')


def build_pdf():
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.enums import TA_LEFT
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.pagesizes import A4
    from pypdf import PdfReader
    font=Path('C:/Windows/Fonts/malgun.ttf')
    if not font.exists(): raise RuntimeError('한글 TTF 없음: PDF 생성하지 않음')
    pdfmetrics.registerFont(TTFont('CorpusKorean',str(font)))
    pdfmetrics.registerFont(TTFont('CorpusKoreanBold','C:/Windows/Fonts/malgunbd.ttf'))
    styles=getSampleStyleSheet()
    for name in ['Normal','Title','Heading1','Heading2']:
        styles[name].fontName='CorpusKorean'
        styles[name].wordWrap='CJK'
    styles['Normal'].fontSize=10
    styles['Normal'].leading=16
    styles['Normal'].spaceAfter=9
    styles['Heading1'].fontSize=16
    styles['Heading1'].leading=24
    styles['Heading1'].spaceBefore=22
    styles['Heading1'].spaceAfter=10
    styles['Heading2'].fontSize=12
    styles['Heading2'].leading=19
    flow=[Paragraph('가상 교육사업 문서 묶음',styles['Title']),Spacer(1,18),Paragraph(DISCLAIMER,styles['Normal']),
          Paragraph('72개 가상 업무 문서 · 핵심 경로 B01~B12 · 전체 자습 선택 경로',styles['Heading2']),
          Paragraph('R01/R02의 기존 v2.0 계산과 검 산 값은 보존한다. 폐기· 예정· 미채택 문서를 현재 기준으로 적용하지 않는다. PDF의 페이지 수는 실제 생성 후 확인한 수만 manifest에 기록한다.',styles['Normal'])]
    flow.append(PageBreak())
    for d in DOCS:
        flow.append(KeepTogether([Paragraph(html.escape(d['id']+' · '+d['title']),styles['Heading1']),
                     Paragraph(html.escape(DISCLAIMER),styles['Normal']),
                     Paragraph(html.escape(f"v{d['version']} | 시행 {d['effectiveDate']} | {d['status']} | {d['scope']}"),styles['Normal']),
                     Paragraph(html.escape(d['summary']),styles['Normal'])]))
        for s in d['sections']:
            flow.extend([Paragraph(html.escape(s['id']+' '+s['title']),styles['Heading2']),
                         Paragraph(html.escape(s['text']).replace('\n','<br/>'),styles['Normal'])])
    def footer(canvas,doc):
        canvas.setFont('CorpusKorean',8)
        canvas.setFillColor(colors.HexColor('#466047'))
        canvas.drawString(42,28,'강사 제작 가상 교육자료 / 운영 기준 v2.0 보존')
        canvas.drawRightString(A4[0]-42,28,str(doc.page))
    dest=OUT/'reference-corpus.pdf'
    SimpleDocTemplate(str(dest),pagesize=A4,rightMargin=44,leftMargin=44,topMargin=44,bottomMargin=48).build(flow,onFirstPage=footer,onLaterPages=footer)
    reader=PdfReader(str(dest))
    extracted=[p.extract_text() or '' for p in reader.pages]
    assert all(len(t.strip())>30 for t in extracted),'blank PDF page'
    joined='\n'.join(extracted)
    for d in DOCS: assert d['title'] in joined, d['id']
    return dict(path=BASE+'reference-corpus.pdf',pageCount=len(reader.pages),
                font='맑은 고딕 TTF',textExtractionVerified=True,allDocumentTitlesFound=True,
                visualReview='생성 후 별도 렌더 확인 기록을 참조; 자동 추출은 시각 검증을 대체하지 않음')


